// Manifest loading and module discovery: search-path order, scanning, shadowing and resolution.
//
// The search-path layouts are generated by the build from tests/fixtures/manifests/layouts/ into
// PRAENORA_TEST_LAYOUTS_DIR; every manifest there describes fx-echo@0.1.0 and points at the
// fixture module's library:
//   primary/fx-echo.pmm.json            this platform, directly in the directory
//   secondary/fx-echo/fx-echo.pmm.json  this platform, in an immediate subdirectory
//   other-platform/fx-echo.pmm.json     another platform
//   deep/one/two/fx-echo.pmm.json       this platform, two levels down
#include "core/semver.hpp"
#include "core/sha256.hpp"
#include "discovery/manifest.hpp"
#include "discovery/module_index.hpp"
#include "discovery/search_paths.hpp"
#include "document/yaml_loader.hpp"
#include "platform/platform.hpp"

#include "module_fixtures.hpp"
#include "scoped_environment.hpp"
#include "test_support.hpp"

#include <praenora/runtime/error.hpp>
#include <praenora/runtime/version.hpp>

#include <gtest/gtest.h>
