namespace {

const praenora::detail::SemVer kVersion = parse_semver("0.1.0");

// Lexically normal, as the runtime reports paths (native separators on Windows).
fs::path layout(std::string_view name) {
    return (utf8_path(PRAENORA_TEST_LAYOUTS_DIR) / utf8_path(name)).lexically_normal();
}

std::string utf8(const fs::path& path) { return path.u8string(); }

bool contains(const std::string& text, const std::string& part) {
    return text.find(part) != std::string::npos;
}

std::string path_list(const std::vector<std::string>& entries) {
#ifdef _WIN32
    const char separator = ';';
#else
    const char separator = ':';
#endif
    std::string list;
    for (std::size_t i = 0; i < entries.size(); ++i) {
        if (i > 0) {
            list += separator;
        }
        list += entries[i];
    }
    return list;
}

// Where a search path comes from, as "<origin>#<index>" ("installation" has no index).
std::string origin_of(const SearchPath& path) {
    return praenora::detail::to_string(path.origin) +
           (path.index ? "#" + std::to_string(*path.index) : std::string());
}

// Where discovery found a manifest, as "<origin>[#<index>]:<file>", or "nowhere".
std::string where(const ModuleManifest& manifest) {
    if (!manifest.location) {
        return "nowhere";
    }
    const ManifestLocation& location = *manifest.location;
    return praenora::detail::to_string(location.origin) +
           (location.index ? "#" + std::to_string(*location.index) : std::string()) + ":" +
           location.file;
}

} // namespace

TEST(Manifest, LoadsGeneratedFixtureManifest) {
    const fs::path path = praenora::test::fixture_manifest("fx-echo");
    const ModuleManifest manifest = load_manifest(path);

    EXPECT_EQ(manifest.name, "fx-echo");
    EXPECT_EQ(praenora::detail::to_string(manifest.version), "0.1.0");
    EXPECT_EQ(manifest.abi_major, 0u);
    EXPECT_EQ(manifest.abi_minor, 0u);
    EXPECT_EQ(praenora::detail::to_string(manifest.pmp_version), "0.1.0");
    EXPECT_EQ(praenora::detail::to_string(manifest.sdk_version), "0.2.0");

    EXPECT_TRUE(manifest.manifest_path.is_absolute());
    EXPECT_TRUE(fs::equivalent(manifest.manifest_path, path));
    EXPECT_EQ(manifest.directory, manifest.manifest_path.parent_path());
    EXPECT_EQ(manifest.library_path.parent_path(), manifest.directory);
    EXPECT_EQ(manifest.library_path.stem().u8string(), "fx-echo");
    EXPECT_TRUE(fs::is_regular_file(manifest.library_path));
    EXPECT_FALSE(manifest.library_sha256.has_value());
    EXPECT_TRUE(manifest.dependency_paths.empty());

    EXPECT_EQ(manifest.os + "-" + manifest.arch, praenora::version_info().platform);
    ASSERT_EQ(manifest.capabilities.size(), 1u);
    EXPECT_EQ(manifest.capabilities[0].id, "test.echo");
    EXPECT_EQ(praenora::detail::to_string(manifest.capabilities[0].version), "0.1.0");

    ASSERT_TRUE(manifest.parameters_schema.is_object());
    EXPECT_EQ(manifest.parameters_schema.at("type"), "object");
    ASSERT_NE(manifest.parameters, nullptr);
    EXPECT_TRUE(manifest.parameters->validate(nlohmann::json::object()).empty());
    EXPECT_FALSE(manifest.parameters->validate(nlohmann::json::array()).empty());

    EXPECT_EQ(manifest.features.concurrency, "module");
    EXPECT_TRUE(manifest.features.diagnostics);
    EXPECT_FALSE(manifest.features.cancellation);
    EXPECT_FALSE(manifest.features.self_test);
    EXPECT_FALSE(manifest.test_vectors.has_value());

    EXPECT_EQ(manifest.manifest_sha256, praenora::detail::sha256_file_hex(path));
}

// requires.services (format 0.2): every entry in manifest order, with the defaults minor 0 and
// optional false; a manifest of format 0.1 declares none.
TEST(Manifest, ReadsTheServicesItRequires) {
    const ModuleManifest generated = load_manifest(praenora::test::fixture_manifest("fx-service"));
    ASSERT_EQ(generated.service_requirements.size(), 2u);
    EXPECT_EQ(praenora::detail::to_string(generated.service_requirements[0].service),
              "test.echo@0.0");
    EXPECT_FALSE(generated.service_requirements[0].optional);
    EXPECT_EQ(praenora::detail::to_string(generated.service_requirements[1].service),
              "test.other@1.0");
    EXPECT_TRUE(generated.service_requirements[1].optional);

    const ModuleManifest minor =
        load_manifest(praenora::test::fixture_manifest("fx-service-minor"));
    ASSERT_EQ(minor.service_requirements.size(), 1u);
    EXPECT_EQ(praenora::detail::to_string(minor.service_requirements[0].service),
              "test.echo@0.7");

    // The defaults of the schema.
    const ModuleManifest defaults = load_manifest(
        praenora::test::fixture_path("documents/valid/module-manifest/requires.pmm.json"));
    ASSERT_EQ(defaults.service_requirements.size(), 2u);
    EXPECT_EQ(praenora::detail::to_string(defaults.service_requirements[0].service),
              "praenora.simulation@0.0");
    EXPECT_EQ(praenora::detail::to_string(defaults.service_requirements[1].service),
              "test.echo@0.0");
    EXPECT_FALSE(defaults.service_requirements[1].optional);

    for (const char* name : {"fx-echo", "fx-service-format-0-1"}) {
        EXPECT_TRUE(load_manifest(praenora::test::fixture_manifest(name))
                        .service_requirements.empty())
            << name;
    }
}

// JSON's -0 is the integer 0, and the schema accepts it as one: every integer of a manifest is read
// by its value.
TEST(Manifest, ReadsIntegersWrittenNegativeZeroAsZero) {
    const ModuleManifest manifest = load_manifest(
        praenora::test::fixture_path("documents/valid/module-manifest/negative-zero.pmm.json"));
    EXPECT_EQ(manifest.abi_major, 0u);
    EXPECT_EQ(manifest.abi_minor, 0u);
    ASSERT_EQ(manifest.service_requirements.size(), 1u);
    EXPECT_EQ(praenora::detail::to_string(manifest.service_requirements[0].service),
              "test.echo@0.0");
}

TEST(Discovery, SearchOrderExplicitBeforeEnvironment) {
    const fs::path primary = layout("primary");
    const fs::path secondary = layout("secondary");
    const fs::path configured = layout("other-platform");
    const auto installed = installation_module_dir();

    {
        // Explicit paths, then configuration paths, then PRAENORA_MODULE_PATH, then the
        // installation default.
        const ScopedEnvironment environment("PRAENORA_MODULE_PATH", utf8(secondary));
        const auto paths = module_search_paths({utf8(primary)}, {configured}, true);
        std::vector<fs::path> expected = {primary, configured, secondary};
        if (installed) {
            expected.push_back(*installed);
        }
        EXPECT_EQ(paths_of(paths), expected);
        // Each path keeps where it comes from.
        EXPECT_EQ(origin_of(paths[0]), "caller#0");
        EXPECT_EQ(origin_of(paths[1]), "configuration#0");
        EXPECT_EQ(origin_of(paths[2]), "environment#0");
        if (installed) {
            EXPECT_EQ(origin_of(paths[3]), "installation");
        }

        // The first match wins: the explicit path's manifest.
        const ModuleIndex index = ModuleIndex::scan(paths);
        const ModuleManifest* found = index.resolve("fx-echo", kVersion);
        ASSERT_NE(found, nullptr);
        EXPECT_EQ(found->directory, primary);
    }
    {
        // The same with the two paths exchanged: order comes from the source, not the names.
        const ScopedEnvironment environment("PRAENORA_MODULE_PATH", utf8(primary));
        const auto paths = module_search_paths({utf8(secondary)}, {}, true);
        ASSERT_GE(paths.size(), 2u);
        EXPECT_EQ(paths[0].path, secondary);
        EXPECT_EQ(paths[1].path, primary);
        const ModuleIndex index = ModuleIndex::scan(paths);
        const ModuleManifest* found = index.resolve("fx-echo", kVersion);
        ASSERT_NE(found, nullptr);
        EXPECT_EQ(found->directory, secondary / "fx-echo");

        // Without use_environment, PRAENORA_MODULE_PATH is ignored.
        const auto without = paths_of(module_search_paths({utf8(secondary)}, {}, false));
        EXPECT_EQ(std::find(without.begin(), without.end(), primary), without.end());
        EXPECT_EQ(without.front(), secondary);
    }
}

TEST(Discovery, ShadowedDuplicateWarnsWithBothPaths) {
    const fs::path first = layout("primary") / "fx-echo.pmm.json";
    const fs::path second = layout("secondary") / "fx-echo" / "fx-echo.pmm.json";
    const ModuleIndex index = ModuleIndex::scan({layout("primary"), layout("secondary")});

    const ModuleManifest* found = index.resolve("fx-echo", kVersion);
    ASSERT_NE(found, nullptr);
    EXPECT_EQ(found->manifest_path, first);
    EXPECT_EQ(index.entries().size(), 2u);

    ASSERT_EQ(index.diagnostics().size(), 1u);
    const Diagnostic& warning = index.diagnostics()[0];
    EXPECT_EQ(warning.severity, Severity::warning);
    EXPECT_TRUE(contains(warning.message, utf8(first))) << warning.message;
    EXPECT_TRUE(contains(warning.message, utf8(second))) << warning.message;
    EXPECT_TRUE(contains(warning.message, "fx-echo@0.1.0")) << warning.message;
    EXPECT_EQ(warning.location.file, utf8(second));
    EXPECT_EQ(warning.module, "fx-echo@0.1.0");
}

TEST(Discovery, OtherPlatformManifestsDoNotShadow) {
    // The other platform's manifest comes first on the search path, and still loses.
    const ModuleIndex index = ModuleIndex::scan({layout("other-platform"), layout("secondary")});
    const ModuleManifest* found = index.resolve("fx-echo", kVersion);
    ASSERT_NE(found, nullptr);
    EXPECT_EQ(found->directory, layout("secondary") / "fx-echo");
    EXPECT_EQ(found->os + "-" + found->arch, praenora::version_info().platform);
    EXPECT_EQ(index.entries().size(), 2u); // indexed, but it shadows nothing
    EXPECT_TRUE(index.diagnostics().empty());

    // With nothing for this platform, resolution reports PLATFORM_MISMATCH.
    const ModuleIndex only_other = ModuleIndex::scan({layout("other-platform")});
    Diagnostic why_not;
    EXPECT_EQ(only_other.resolve("fx-echo", kVersion, &why_not), nullptr);
    EXPECT_EQ(why_not.code, ErrorCode::PLATFORM_MISMATCH);
    EXPECT_EQ(why_not.severity, Severity::error);
    EXPECT_TRUE(contains(why_not.message, praenora::version_info().platform)) << why_not.message;
    EXPECT_TRUE(contains(why_not.message, utf8(layout("other-platform") / "fx-echo.pmm.json")))
        << why_not.message;
    EXPECT_EQ(why_not.module, "fx-echo@0.1.0");
}

TEST(Discovery, NotFoundListsSearchedPaths) {
    const praenora::test::ScratchDir scratch;
    const std::vector<fs::path> paths = {layout("primary"), scratch.path() / "missing",
                                         layout("other-platform")};
    const ModuleIndex index = ModuleIndex::scan(paths);
    EXPECT_TRUE(index.diagnostics().empty()); // a missing directory is not a problem

    Diagnostic why_not;
    EXPECT_EQ(index.resolve("fx-absent", kVersion, &why_not), nullptr);
    EXPECT_EQ(why_not.code, ErrorCode::MODULE_NOT_FOUND);
    EXPECT_EQ(why_not.severity, Severity::error);
    EXPECT_TRUE(contains(why_not.message, "fx-absent@0.1.0")) << why_not.message;
    for (const auto& path : paths) {
        EXPECT_TRUE(contains(why_not.message, utf8(path))) << why_not.message;
    }
    EXPECT_EQ(why_not.module, "fx-absent@0.1.0");

    // A known module at another version is not found either; the message names what exists.
    Diagnostic other_version;
    EXPECT_EQ(index.resolve("fx-echo", parse_semver("0.2.0"), &other_version), nullptr);
    EXPECT_EQ(other_version.code, ErrorCode::MODULE_NOT_FOUND);
    EXPECT_TRUE(contains(other_version.message, "0.1.0")) << other_version.message;

    EXPECT_EQ(index.resolve("fx-absent", kVersion), nullptr); // why_not is optional
}

TEST(Discovery, EnvironmentPathListSplit) {
    const fs::path a = layout("primary");
    const fs::path b = layout("secondary");
    const fs::path c = layout("other-platform");
    const auto installed = installation_module_dir();
    {
        // Empty entries are skipped and a repeated entry is kept once, in its first place.
        const ScopedEnvironment environment("PRAENORA_MODULE_PATH",
                                            path_list({utf8(a), utf8(b), "", utf8(c), utf8(a)}));
        std::vector<fs::path> expected = {a, b, c};
        if (installed) {
            expected.push_back(*installed);
        }
        const auto paths = module_search_paths({}, {}, true);
        EXPECT_EQ(paths_of(paths), expected);
        // Indexes count the variable's non-empty entries: c is the third.
        EXPECT_EQ(origin_of(paths[0]), "environment#0");
        EXPECT_EQ(origin_of(paths[1]), "environment#1");
        EXPECT_EQ(origin_of(paths[2]), "environment#2");
    }
    {
        // A relative entry is relative to the current directory.
        const ScopedEnvironment environment("PRAENORA_MODULE_PATH", "relative modules");
        const auto paths = module_search_paths({}, {}, true);
        ASSERT_FALSE(paths.empty());
        EXPECT_EQ(paths.front().path,
                  (fs::current_path() / utf8_path("relative modules")).lexically_normal());
    }
    {
        // Unset, the variable adds nothing; only the installation default remains.
        const ScopedEnvironment environment("PRAENORA_MODULE_PATH", std::nullopt);
        EXPECT_EQ(module_search_paths({}, {}, true).size(), installed ? 1u : 0u);
    }
    if (installed) {
        EXPECT_TRUE(installed->is_absolute());
        EXPECT_EQ(installed->filename().u8string(), "modules");
        EXPECT_EQ(installed->parent_path().filename().u8string(), "praenora");
    }
}

TEST(Discovery, ScansOnlyImmediateSubdirectories) {
    // deep/one/two/fx-echo.pmm.json is two levels below "deep": out of reach.
    const ModuleIndex deep = ModuleIndex::scan({layout("deep")});
    EXPECT_TRUE(deep.entries().empty());
    EXPECT_EQ(deep.resolve("fx-echo", kVersion), nullptr);

    // From "deep/one" it is in an immediate subdirectory.
    const ModuleIndex closer = ModuleIndex::scan({layout("deep") / "one"});
    ASSERT_EQ(closer.entries().size(), 1u);
    EXPECT_NE(closer.resolve("fx-echo", kVersion), nullptr);
}

TEST(Discovery, InvalidManifestsBecomeWarnings) {
    const fs::path bad = praenora::test::fixture_path("manifests/bad");
    const ModuleIndex index = ModuleIndex::scan({bad});
    EXPECT_TRUE(index.entries().empty());

    std::size_t manifests = 0;
    for (const auto& entry : fs::directory_iterator(bad)) {
        const std::string name = entry.path().filename().u8string();
        if (name.size() > 9 && name.compare(name.size() - 9, 9, ".pmm.json") == 0) {
            ++manifests;
        }
    }
    ASSERT_EQ(index.diagnostics().size(), manifests);
    for (const auto& diagnostic : index.diagnostics()) {
        SCOPED_TRACE(diagnostic.location.file);
        EXPECT_EQ(diagnostic.severity, Severity::warning);
        fs::path expect_path = utf8_path(diagnostic.location.file);
        expect_path.replace_extension(".expect.json");
        const auto expect = praenora::detail::load_document_file(expect_path).json;
        EXPECT_EQ(praenora::error_code_info(diagnostic.code).name,
                  expect.at("code").get<std::string>());
    }
}

// Each indexed manifest knows where discovery found it: the search path that reached it first, by
// origin and index, and the manifest file relative to that path, '/'-separated.
TEST(Discovery, RecordsWhereEachManifestWasFound) {
    const fs::path primary = layout("primary");
    const fs::path secondary = layout("secondary");
    {
        // Each origin counts its paths from 0.
        const ModuleIndex index =
            ModuleIndex::scan(module_search_paths({utf8(primary)}, {secondary}, false));
        const auto entries = index.entries();
        ASSERT_EQ(entries.size(), 2u);
        EXPECT_EQ(where(*entries[0]), "caller#0:fx-echo.pmm.json");
        EXPECT_EQ(where(*entries[1]), "configuration#0:fx-echo/fx-echo.pmm.json");
    }
    {
        // A configuration path that repeats a caller's path is searched once, as the caller's;
        // it still counts among the configuration's paths.
        const auto paths = module_search_paths({utf8(primary)}, {primary, secondary}, false);
        ASSERT_GE(paths.size(), 2u);
        EXPECT_EQ(origin_of(paths[0]), "caller#0");
        EXPECT_EQ(origin_of(paths[1]), "configuration#1");
        const ModuleIndex index = ModuleIndex::scan(paths);
        const auto entries = index.entries();
        ASSERT_EQ(entries.size(), 2u);
        EXPECT_EQ(where(*entries[0]), "caller#0:fx-echo.pmm.json");
        EXPECT_EQ(where(*entries[1]), "configuration#1:fx-echo/fx-echo.pmm.json");
    }
    {
        // A caller's path that repeats an earlier one still counts.
        const ModuleIndex index = ModuleIndex::scan(module_search_paths(
            {utf8(primary), utf8(primary), utf8(layout("other-platform"))}, {}, false));
        const auto entries = index.entries();
        ASSERT_EQ(entries.size(), 2u);
        EXPECT_EQ(where(*entries[1]), "caller#2:fx-echo.pmm.json");
    }
    {
        // PRAENORA_MODULE_PATH: the position among the variable's non-empty entries.
        const ScopedEnvironment environment(
            "PRAENORA_MODULE_PATH",
            path_list({"", utf8(layout("other-platform")), utf8(secondary)}));
        const ModuleIndex index = ModuleIndex::scan(module_search_paths({}, {}, true));
        const auto entries = index.entries();
        ASSERT_EQ(entries.size(), 2u);
        EXPECT_EQ(where(*entries[0]), "environment#0:fx-echo.pmm.json");
        EXPECT_EQ(where(*entries[1]), "environment#1:fx-echo/fx-echo.pmm.json");
    }
    {
        // A file reached through two overlapping paths: relative to the first that reaches it.
        const ModuleIndex inner_first = ModuleIndex::scan({secondary / "fx-echo", secondary});
        ASSERT_EQ(inner_first.entries().size(), 1u);
        EXPECT_EQ(where(*inner_first.entries()[0]), "caller#0:fx-echo.pmm.json");
        const ModuleIndex outer_first = ModuleIndex::scan({secondary, secondary / "fx-echo"});
        ASSERT_EQ(outer_first.entries().size(), 1u);
        EXPECT_EQ(where(*outer_first.entries()[0]), "caller#0:fx-echo/fx-echo.pmm.json");
    }
    // The installation's directory has no index.
    if (const auto installed = installation_module_dir()) {
        const auto paths = module_search_paths({}, {}, false);
        ASSERT_EQ(paths.size(), 1u);
        EXPECT_EQ(origin_of(paths[0]), "installation");
        const ManifestLocation location =
            manifest_location(paths[0], paths[0].path / "fx-echo" / "fx-echo.pmm.json");
        EXPECT_EQ(location.origin, SearchPathOrigin::installation);
        EXPECT_FALSE(location.index.has_value());
        EXPECT_EQ(location.file, "fx-echo/fx-echo.pmm.json");
    }
    // A manifest read directly was found on no search path.
    EXPECT_EQ(where(load_manifest(praenora::test::fixture_manifest("fx-echo"))), "nowhere");
}

// A module's parameters_schema is draft-07 (also without `$schema`) or 2020-12; anything else is
// refused when the manifest is read.
namespace {

ModuleManifest manifest_with_parameters(const praenora::test::ScratchDir& scratch,
                                        const nlohmann::json& parameters_schema) {
    const fs::path source = praenora::test::fixture_manifest("fx-echo");
    nlohmann::json document = praenora::detail::load_document_file(source).json;
    const fs::path library = load_manifest(source).library_path;
    fs::copy_file(library, scratch.path() / library.filename(),
                  fs::copy_options::overwrite_existing);
    document["library"]["path"] = library.filename().u8string();
    document["parameters_schema"] = parameters_schema;
    const fs::path path = scratch.path() / "module.pmm.json";
    std::ofstream(path, std::ios::binary) << document.dump(2);
    return load_manifest(path);
}

} // namespace

TEST(Manifest, ParametersSchemaMayBe2020OrDraft07) {
    const praenora::test::ScratchDir scratch;
    const ModuleManifest modern = manifest_with_parameters(scratch, nlohmann::json::parse(R"({
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "type": "object",
      "$defs": {"fraction": {"type": "number", "minimum": 0, "maximum": 1, "default": 0.5}},
      "properties": {"gain": {"$ref": "#/$defs/fraction"}},
      "unevaluatedProperties": false})"));
    std::vector<praenora::detail::SchemaIssue> issues;
    EXPECT_EQ(modern.parameters->apply_defaults(nlohmann::json::object(), issues).at("gain"), 0.5);
    EXPECT_TRUE(issues.empty());
    EXPECT_FALSE(modern.parameters->validate(nlohmann::json::parse(R"({"gain": 2})")).empty());
    EXPECT_FALSE(modern.parameters->validate(nlohmann::json::parse(R"({"other": 1})")).empty());

    // Without `$schema` the schema is draft-07.
    const ModuleManifest plain = manifest_with_parameters(scratch, nlohmann::json::parse(R"({
      "type": "object",
      "definitions": {"fraction": {"type": "number", "maximum": 1, "default": 0.25}},
      "properties": {"gain": {"$ref": "#/definitions/fraction"}}})"));
    EXPECT_EQ(plain.parameters->apply_defaults(nlohmann::json::object(), issues).at("gain"), 0.25);
    EXPECT_FALSE(plain.parameters->validate(nlohmann::json::parse(R"({"gain": 2})")).empty());
}

TEST(Manifest, ParametersSchemaOfAnotherDialectOrWithACycleIsRefused) {
    for (const char* text : {
             R"({"$schema": "https://json-schema.org/draft/2019-09/schema", "type": "object"})",
             R"({"$schema": "http://json-schema.org/draft-04/schema#", "type": "object"})",
             R"({"$ref": "#"})",
         }) {
        SCOPED_TRACE(text);
        const praenora::test::ScratchDir scratch;
        try {
            manifest_with_parameters(scratch, nlohmann::json::parse(text));
            FAIL() << "the manifest was accepted";
        } catch (const praenora::Error& error) {
            EXPECT_EQ(error.code(), ErrorCode::MANIFEST_INVALID);
            EXPECT_TRUE(contains(error.what(), "not a valid JSON Schema")) << error.what();
        }
    }
}
